using System;
using System.Linq;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
using Xunit;
namespace RPCore.Tests
{
    public class TrafficTests
    {
        static readonly Action Save=()=>{};
        static TrafficOptions C()=>TrafficOptions.Defaults();
        static TrafficFrame F()=>new TrafficFrame{Car=true,Belt=true,Helmet=true,Lights=true,Engine=1000,Speed=10,Street="Alta St"};
        static WalletData W()=>new WalletData{Cash=123,Bank=10000,Traffic=new TrafficData{Enabled=true}};
        static TrafficTicket Ticket(string id="citation")=>new TrafficTicket{Id=id,Model=123,Plate="RPTEST",Street="Alta St",LimitMph=50,Lines={new TrafficLine{Code=TrafficOffence.NoSeatbelt,Amount=150}}};
        static WalletData Begin(){var w=W();Assert.True(TrafficTransactions.Begin(w,Ticket(),Save,out bool changed));Assert.True(changed);return w;}
        static WalletData Finished(string outcome="served"){var w=Begin();Assert.True(TrafficTransactions.Finish(w,"citation",outcome,Save,out _));return w;}
        [Fact] public void LegacyWalletHasNoAutomaticEnforcementOrCharges(){var w=JsonConvert.DeserializeObject<WalletData>("{\"Cash\":123,\"Bank\":456,\"Future\":7}");Assert.Null(w.Traffic);Assert.False(new TrafficData().Enabled);Assert.True(new TrafficData().Valid);}
        [Fact] public void SourceStreetTableHasAllOneHundredSixtyTwoEntriesInMph(){var c=C();Assert.True(c.Valid);Assert.Equal(162,c.SpeedLimits.Count);Assert.Equal(50,TrafficRules.Limit(c,"Alta St"));Assert.Equal(70,TrafficRules.Limit(c,"Senora Freeway"));Assert.Equal(40,TrafficRules.Limit(c,"Davis Ave"));Assert.Equal(0,TrafficRules.Limit(c,"Unknown avenue"));Assert.Equal(50,c.WitnessRadius);}
        [Fact] public void CompliantCarProducesNoOffence(){Assert.Empty(TrafficRules.Evaluate(F(),C()));}
        [Fact] public void SpeedUsesMphAndSevereThresholdFromReference(){var f=F();f.Speed=60f/2.2369363f;var line=Assert.Single(TrafficRules.Evaluate(f,C()));Assert.Equal(TrafficOffence.Speeding,line.Code);Assert.Equal(150,line.Amount);f.Speed=81f/2.2369363f;line=Assert.Single(TrafficRules.Evaluate(f,C()));Assert.Equal(250,line.Amount);Assert.Equal(250,TrafficRules.Cost(TrafficOffence.Speeding,30));Assert.Equal(150,TrafficRules.Cost(TrafficOffence.Speeding,29.99));}
        [Fact] public void UnknownStreetCannotInventSpeedingFine(){var f=F();f.Street="Unknown";f.Speed=90;Assert.Empty(TrafficRules.Evaluate(f,C()));}
        [Fact] public void SeatbeltAndNightLightsNeedMovement(){var f=F();f.Belt=false;f.Lights=false;f.Night=true;f.Speed=0;Assert.Empty(TrafficRules.Evaluate(f,C()));f.Speed=10;var lines=TrafficRules.Evaluate(f,C());Assert.Equal(2,lines.Count);Assert.Equal(150,lines.Single(l=>l.Code==TrafficOffence.NoSeatbelt).Amount);Assert.Equal(100,lines.Single(l=>l.Code==TrafficOffence.NoHeadlights).Amount);f.Night=false;Assert.Single(TrafficRules.Evaluate(f,C()));}
        [Fact] public void MotorcycleNeedsHelmetAndNeverCarSeatbelt(){var f=F();f.Car=false;f.Bike=true;f.Belt=false;f.Helmet=false;var line=Assert.Single(TrafficRules.Evaluate(f,C()));Assert.Equal(TrafficOffence.NoHelmet,line.Code);Assert.Equal(120,line.Amount);}
        [Fact] public void MechanicalAndBurnoutFinesAreDistinctAndChargedOnceEach(){var f=F();f.Burst=true;f.Burnout=true;f.Engine=300;var lines=TrafficRules.Evaluate(f,C());Assert.Equal(3,lines.Count);Assert.Equal(275,lines.Sum(l=>l.Amount));Assert.Equal(3,lines.Select(l=>l.Code).Distinct().Count());}
        [Fact] public void InvalidFrameCannotGenerateFine(){var f=F();f.Speed=float.NaN;Assert.Empty(TrafficRules.Evaluate(f,C()));f=F();f.Engine=float.PositiveInfinity;Assert.Empty(TrafficRules.Evaluate(f,C()));f=F();f.Car=false;Assert.Empty(TrafficRules.Evaluate(f,C()));}
        [Fact] public void WitnessRequiresContinuousSameEvidenceAndLosesProofOnBlindSpot(){var m=new TrafficWitnessMeter();Assert.False(m.Observe("car:street:belt",500,2000));for(int i=0;i<3;i++)Assert.False(m.Observe("car:street:belt",500,2000));Assert.True(m.Observe("car:street:belt",500,2000));Assert.False(m.Observe(null,500,2000));Assert.Equal(0,m.Elapsed);Assert.False(m.Observe("car:street:belt",500,2000));}
        [Fact] public void EvidenceChangesAndInvalidDeltaResetHold(){var m=new TrafficWitnessMeter();m.Observe("a",0,2000);m.Observe("a",1000,2000);Assert.False(m.Observe("b",500,2000));Assert.Equal(0,m.Elapsed);Assert.False(m.Observe("b",2000,2000));Assert.Equal(0,m.Elapsed);}
        [Fact] public void BeginCapturesWitnessSnapshotWithoutTouchingBankOrCash(){var w=W();var t=Ticket();int saves=0;Assert.True(TrafficTransactions.Begin(w,t,()=>saves++,out _));t.Lines[0].Amount=1;t.Plate="changed";Assert.Equal(150,w.Traffic.Tickets[0].Total);Assert.Equal("RPTEST",w.Traffic.Tickets[0].Plate);Assert.Equal(10000,w.Bank);Assert.Equal(123,w.Cash);Assert.Equal(1,saves);Assert.Equal("citation",w.Traffic.Pending);}
        [Fact] public void DisabledPendingAndRepeatedTicketCannotBegin(){var w=W();w.Traffic.Enabled=false;Assert.False(TrafficTransactions.Begin(w,Ticket(),Save,out _));w=Begin();Assert.False(TrafficTransactions.Begin(w,Ticket("other"),Save,out _));TrafficTransactions.Finish(w,"citation","served",Save,out _);Assert.False(TrafficTransactions.Begin(w,Ticket(),Save,out _));}
        [Theory][InlineData("served")][InlineData("evaded")][InlineData("interrupted")]
        public void FinishingStopKeepsActualDebtAndNoAutomaticDebit(string outcome){var w=Finished(outcome);Assert.Null(w.Traffic.Pending);Assert.Equal(outcome,w.Traffic.Tickets[0].Outcome);Assert.False(w.Traffic.Tickets[0].Paid);Assert.Equal(150,w.Traffic.Tickets[0].Total);Assert.Equal(10000,w.Bank);Assert.Equal(123,w.Cash);}
        [Fact] public void FinishReplayNeverChangesOutcomeOrSavesAgain(){var w=Finished();Assert.True(TrafficTransactions.Finish(w,"citation","served",()=>throw new Exception(),out bool changed));Assert.False(changed);Assert.False(TrafficTransactions.Finish(w,"citation","evaded",Save,out _));Assert.False(TrafficTransactions.Finish(w,"wrong","served",Save,out _));}
        [Fact] public void PaymentUsesExactBankOnlyAndOneWalletCheckpoint(){var w=Finished();int saves=0;Assert.True(TrafficTransactions.Pay(w,"citation",()=>saves++,out bool changed));Assert.True(changed);Assert.Equal(9850,w.Bank);Assert.Equal(123,w.Cash);Assert.True(w.Traffic.Tickets[0].Paid);Assert.Equal(1,w.Traffic.Paid);Assert.Equal(150,w.Traffic.Collected);Assert.Equal(1,saves);}
        [Fact] public void RepeatedPaymentNeverDebitsOrSaves(){var w=Finished();TrafficTransactions.Pay(w,"citation",Save,out _);Assert.True(TrafficTransactions.Pay(w,"citation",()=>throw new Exception(),out bool changed));Assert.False(changed);Assert.Equal(9850,w.Bank);Assert.Equal(1,w.Traffic.Paid);}
        [Fact] public void InsufficientBankDoesNotTakePartialBankOrCash(){var w=Finished();w.Bank=149;w.Cash=5000;Assert.False(TrafficTransactions.Pay(w,"citation",Save,out _));Assert.Equal(149,w.Bank);Assert.Equal(5000,w.Cash);Assert.False(w.Traffic.Tickets[0].Paid);}
        [Fact] public void ActiveOpenStopCannotBePaidBeforeOutcomeIsRecorded(){var w=Begin();Assert.False(TrafficTransactions.Pay(w,"citation",Save,out _));Assert.Equal(10000,w.Bank);Assert.Equal("citation",w.Traffic.Pending);}
        [Fact] public void AllFinancialAndRecordSavesRollBackSynchronously(){var w=W();string before=JsonConvert.SerializeObject(w);Assert.Throws<Exception>(()=>TrafficTransactions.Begin(w,Ticket(),()=>throw new Exception(),out _));Assert.Equal(before,JsonConvert.SerializeObject(w));w=Begin();before=JsonConvert.SerializeObject(w);Assert.Throws<Exception>(()=>TrafficTransactions.Finish(w,"citation","served",()=>throw new Exception(),out _));Assert.Equal(before,JsonConvert.SerializeObject(w));w=Finished();before=JsonConvert.SerializeObject(w);Assert.Throws<Exception>(()=>TrafficTransactions.Pay(w,"citation",()=>throw new Exception(),out _));Assert.Equal(before,JsonConvert.SerializeObject(w));}
        [Fact] public void PreferenceRollbackAndDisablingNeverEraseDebt(){var w=Finished();string before=JsonConvert.SerializeObject(w);Assert.Throws<Exception>(()=>TrafficTransactions.Configure(w,false,()=>throw new Exception(),out _));Assert.Equal(before,JsonConvert.SerializeObject(w));Assert.True(TrafficTransactions.Configure(w,false,Save,out _));Assert.Single(w.Traffic.Tickets);Assert.True(TrafficTransactions.Pay(w,"citation",Save,out _));Assert.False(w.Traffic.Enabled);}
        [Fact] public void ReloadedPendingBecomesInterruptedWithSameAmountAndProof(){var w=JsonConvert.DeserializeObject<WalletData>(JsonConvert.SerializeObject(Begin()));Assert.True(TrafficTransactions.Finish(w,"citation","interrupted",Save,out _));Assert.Equal(150,w.Traffic.Tickets[0].Total);Assert.Null(w.Traffic.Pending);Assert.True(TrafficTransactions.Pay(w,"citation",Save,out _));}
        [Fact] public void UnknownMetadataSurvivesBankPayment(){var j=JObject.FromObject(Finished());j["FutureWallet"]=7;j["Traffic"]["FutureBook"]="keep";j["Traffic"]["Tickets"][0]["FutureTicket"]="keep";j["Traffic"]["Tickets"][0]["Lines"][0]["FutureEvidence"]=42;var w=j.ToObject<WalletData>();TrafficTransactions.Pay(w,"citation",Save,out _);j=JObject.FromObject(w);Assert.Equal(7,(int)j["FutureWallet"]);Assert.Equal("keep",(string)j["Traffic"]["FutureBook"]);Assert.Equal("keep",(string)j["Traffic"]["Tickets"][0]["FutureTicket"]);Assert.Equal(42,(int)j["Traffic"]["Tickets"][0]["Lines"][0]["FutureEvidence"]);}
        [Fact] public void FullUnpaidBookRefusesNewDebtInsteadOfDiscardingOldFine(){var w=W();w.Traffic.Tickets=Enumerable.Range(0,256).Select(i=>{var t=Ticket("id"+i);t.Outcome="served";return t;}).ToList();w.Traffic.Issued=256;Assert.True(w.Traffic.Valid);Assert.False(TrafficTransactions.Begin(w,Ticket(),Save,out _));Assert.Equal(256,w.Traffic.Tickets.Count);}
        [Fact] public void FullBookPrunesOnlyPaidEntryAndPreservesHistoricalPaidCounters(){var w=W();w.Traffic.Tickets=Enumerable.Range(0,256).Select(i=>{var t=Ticket("id"+i);t.Outcome="served";t.Paid=i==0;return t;}).ToList();w.Traffic.Issued=256;w.Traffic.Paid=1;w.Traffic.Collected=150;Assert.True(TrafficTransactions.Begin(w,Ticket(),Save,out _));Assert.Equal(256,w.Traffic.Tickets.Count);Assert.DoesNotContain(w.Traffic.Tickets,t=>t.Id=="id0");Assert.Contains(w.Traffic.Tickets,t=>t.Id=="id1");Assert.Equal(1,w.Traffic.Paid);Assert.Equal(150,w.Traffic.Collected);}
        [Fact] public void InvalidAmountsDuplicateCodesAndCounterOverflowAreProtected(){var t=Ticket();t.Lines[0].Amount=1;Assert.False(t.Valid);t=Ticket();t.Lines.Add(t.Lines[0]);Assert.False(t.Valid);var w=Finished();w.Traffic.Collected=long.MaxValue;Assert.False(TrafficTransactions.Pay(w,"citation",Save,out _));Assert.Equal(10000,w.Bank);w=W();w.Traffic.Issued=long.MaxValue;Assert.False(TrafficTransactions.Begin(w,Ticket(),Save,out _));}
        [Fact] public void CorruptBookCannotBeSilentlyReplacedByPreferenceChange(){var w=W();w.Traffic.Issued=-1;Assert.False(TrafficTransactions.Configure(w,true,Save,out _));Assert.Equal(-1,w.Traffic.Issued);}
        [Theory][InlineData(true,0,0,18,true)][InlineData(true,.5f,0,10,false)][InlineData(false,0,0,10,false)][InlineData(true,0,2,10,false)][InlineData(true,0,0,19,false)]public void OfficerOnlyExitsForSameStoppedDriverAndNearbyStoppedPatrol(bool driver,float speed,float patrol,float distance,bool expected)=>Assert.Equal(expected,TrafficRules.Stopped(driver,speed,patrol,distance));
        [Theory][InlineData(true,true,0,2.5f,true)][InlineData(true,true,.5f,2,false)][InlineData(false,true,0,2,false)][InlineData(true,false,0,2,false)][InlineData(true,true,0,3,false)]public void InspectionNeedsLivingOfficerContinuousProximityAndStoppedDriver(bool driver,bool alive,float speed,float distance,bool expected)=>Assert.Equal(expected,TrafficRules.Inspect(driver,alive,speed,distance));
        [Fact] public void ConfigAndEvidenceRejectInvalidNumbers(){var c=C();c.WitnessRadius=0;Assert.False(c.Valid);c=C();c.SpeedLimits["new road"]=0;Assert.False(c.Valid);Assert.False(new TrafficLine{Code=TrafficOffence.Speeding,Amount=150,Value=-1}.Valid);Assert.False(new TrafficLine{Code=TrafficOffence.SmokingEngine,Amount=75,Value=900}.Valid);Assert.False(TrafficRules.Inspect(true,true,float.NaN,1));}
    }
}
